return {["fb28_01"]={["dsc"]=[[从终南山走来，你进入了一条狭窄的山路，蜿蜒曲折，前方似乎是终南山的主峰了。]],["fightBackground"]=[[山外]],["id"]=[[fb28_01]],["name"]=[[终南山小道]],["permission"]=1,["right"]=[[fb28_02]],["stepMusic"]=[[jiaobu]]},["fb28_02"]={["down"]=[[fb28_03]],["dsc"]=[[此时你已身在终南山主峰，视野更为广阔。重阳宫的翠绿琉瓦在山腰处，晶莹生辉。只见不少殿宇散布於山坳间，景色颇为美妙。]],["fightBackground"]=[[山外]],["id"]=[[fb28_02]],["item1"]=[[fb28item6]],["left"]=[[fb28_01]],["name"]=[[终南山主峰]],["permission"]=1,["right"]=[[fb28_27]],["role1"]=[[znq3cd10]],["stepMusic"]=[[jiaobu]]},["fb28_03"]={["down"]=[[fb28_04]],["dsc"]=[[这条山路盘终南山主峰而上，山路贴着石璧凿出，只容一人可过，形势极为险峻。往远处望去。群山环绕，列於脚下，百里美景尽收眼底，顿时令人豪气陡生，想要长啸一声。]],["fightBackground"]=[[山外]],["id"]=[[fb28_03]],["name"]=[[山路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_02]]},["fb28_04"]={["down"]=[[fb28_05]],["dsc"]=[[这是终南山山腰处的一块空地，地势平坦。北面一条小路直攀山璧而上，通往是终南山主峰。]],["fightBackground"]=[[山内]],["id"]=[[fb28_04]],["item1"]=[[bfitem3]],["name"]=[[空地]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_03]]},["fb28_05"]={["down"]=[[fb28_29]],["dsc"]=[[这是一片小树林，周围的树木都很高。间杂着一些叫不出名字的鲜花，五彩缤纷。你隐隐地有些担心起来:不会迷路了吧，转头间却看见西南边似乎有一条小路。]],["fightBackground"]=[[森林内]],["id"]=[[fb28_05]],["leftDown"]=[[fb28_06]],["name"]=[[小树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_04]]},["fb28_06"]={["dsc"]=[[这是一片小树林，周围的树木都很高。间杂着一些叫不出名字的鲜花，五彩缤纷。你隐隐地有些担心起来:不会迷路了吧，转头间却看见西南边似乎有一条小路。]],["fightBackground"]=[[森林内]],["id"]=[[fb28_06]],["leftDown"]=[[fb28_07]],["name"]=[[小树林]],["permission"]=1,["rightUp"]=[[fb28_05]],["stepMusic"]=[[jiaobu]]},["fb28_07"]={["down"]=[[fb28_08]],["dsc"]=[[这是一片小树林，周围的树木都很高。间杂着一些叫不出名字的鲜花，五彩缤纷。你隐隐地有些担心起来:不会迷路了吧，转头间却看见西南边似乎有一条小路。]],["fightBackground"]=[[森林内]],["id"]=[[fb28_07]],["name"]=[[小树林]],["permission"]=1,["rightUp"]=[[fb28_06]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb28_08"]={["down"]=[[fb28_11]],["dsc"]=[[这里是一片草地，草很深，几乎淹没了小腿。草间散布着一些奇花，微风吹过，芬芳扑鼻。你听到时而有“嗡嗡”的声音，看见有一些个头奇大的蜜蜂在草地上飞舞盘旋。]],["fightBackground"]=[[森林外]],["id"]=[[fb28_08]],["name"]=[[草地]],["permission"]=1,["right"]=[[fb28_09]],["role1"]=[[fb28r08_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb28_07]]},["fb28_09"]={["dsc"]=[[这里是一片草地，草很深，几乎淹没了小腿。草间散布着一些奇花，微风吹过，芬芳扑鼻。你听到时而有“嗡嗡”的声音，看见有一些个头奇大的蜜蜂在草地上飞舞盘旋。]],["fightBackground"]=[[森林外]],["id"]=[[fb28_09]],["left"]=[[fb28_08]],["name"]=[[草地]],["permission"]=1,["rightDown"]=[[fb28_12]],["stepMusic"]=[[jiaobu]]},["fb28_10"]={["dsc"]=[[此处位於终南山西部。只见远处王曲原上，孤立着一座由荒沙堆积而成的山岭。据当地人说，这是在商朝，一位名叫陆亚仙的人，用法力遣来一股黄沙而成。]],["id"]=[[fb28_10]],["item1"]=[[fb28item21]],["name"]=[[黄沙岭]],["permission"]=1,["right"]=[[fb28_11]],["stepMusic"]=[[jiaobu]]},["fb28_11"]={["down"]=[[fb28_14]],["dsc"]=[[你走过了草地，眼前突然了一片开阔地，突兀地耸立着一座大墓，墓上砌的石头已经斑驳了，看的出来这是座古陵。墓前没有立碑，也没有任何的标记，黑黝的墓门紧闭着。]],["id"]=[[fb28_11]],["item1"]=[[fb28item15]],["item2"]=[[fb28item104]],["item3"]=[[fb28item105]],["left"]=[[fb28_10]],["name"]=[[墓门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_08]]},["fb28_12"]={["dsc"]=[[这里是草地的边缘，青草已经很稀疏了，你的面前是一个清波荡漾的大水潭，水很清，隐约可以见过水底的物事，阳光映照下，潭中竟出现彩虹，望着这般美景，你俗念尽消。]],["id"]=[[fb28_12]],["item1"]=[[fb28item7]],["item2"]=[[ycitem1]],["item3"]=[[2019qxhdd1]],["leftUp"]=[[fb28_09]],["name"]=[[寒水潭]],["permission"]=1,["role1"]=[[fb28r12_1]],["stepMusic"]=[[jiaobu]]},["fb28_13"]={["down"]=[[fb28_19]],["dsc"]=[[这是间很大的房间，光线非常昏暗。房里没有什么别的东西，只有中间放着一张收拾得舒舒服服的大床，床上的被褥也整理得整整洁洁，看着就让人想睡觉。]],["id"]=[[fb28_13]],["item1"]=[[fb28item5]],["item2"]=[[fb28item20]],["item3"]=[[fb28item100]],["name"]=[[休息室]],["permission"]=1,["right"]=[[fb28_14]],["rightDown"]=[[fb28_15]],["role1"]=[[fb28r13_1]],["role2"]=[[fb28r13_2]],["role3"]=[[fb28r13_3]],["stepMusic"]=[[jiaobu]]},["fb28_14"]={["down"]=[[fb28_16]],["dsc"]=[[这里是古陵的前厅，光线很差，全靠大厅正中间的梁上悬挂着一颗夜明珠，映射出淡淡的黄光。厅柱是由石头砌成的，上面似乎还写着一些什么字--你怎么也看不清楚了。]],["id"]=[[fb28_14]],["item1"]=[[fb28item16]],["item2"]=[[fb28item103]],["left"]=[[fb28_13]],["name"]=[[前厅]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_11]]},["fb28_15"]={["dsc"]=[[这里是远离正厅的一间小屋，收拾得整整洁洁一尘不染。摆设就如普通人家一般，红木的桌椅，细瓷的杯壶，沉香的大床。你简直无法想像这古陵之中还有这等摆设。]],["id"]=[[fb28_15]],["leftUp"]=[[fb28_13]],["name"]=[[小屋]],["permission"]=1,["right"]=[[fb28_16]],["stepMusic"]=[[jiaobu]]},["fb28_16"]={["down"]=[[fb28_20]],["dsc"]=[[你走进了一间小屋，房间很小，除了一张小床放不下别的东西了。床上好像有几件叠得整整齐齐的粗布衫，洗的干干净净。]],["id"]=[[fb28_16]],["item1"]=[[fb28item102]],["left"]=[[fb28_15]],["name"]=[[小厅]],["permission"]=1,["right"]=[[fb28_17]],["stepMusic"]=[[jiaobu]],["up"]=[[fb28_14]]},["fb28_17"]={["dsc"]=[[这里是龙仙姑喂养训练寒蜂的蜂屋，屋角上挂着很多个六角形的蜂巢，还未进门，就闻得到一阵蜂蜜的甜香。你似乎可以做寒蜂浆。]],["id"]=[[fb28_17]],["item1"]=[[fb28item1]],["left"]=[[fb28_16]],["name"]=[[蜂屋]],["permission"]=1,["right"]=[[fb28_18]],["stepMusic"]=[[jiaobu]]},["fb28_18"]={["dsc"]=[[你走进了一间小屋，房间很小，除了一张小床放不下别的东西了。床上好像有几件叠得整整齐齐的粗布衫，洗的干干净净。]],["id"]=[[fb28_18]],["item1"]=[[fb28item19]],["left"]=[[fb28_17]],["name"]=[[小屋]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb28_19"]={["dsc"]=[[这座石室形状甚是奇特，前窄後宽，成为梯形，东边半圆，西边却作三角形状，原来这是以前重阳祖师的练功室，前窄练掌，後宽使拳，东圆研剑，西角发镖。]],["id"]=[[fb28_19]],["item1"]=[[bfitem1]],["name"]=[[练功室]],["permission"]=1,["right"]=[[fb28_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb28_13]]},["fb28_20"]={["down"]=[[fb28_21]],["dsc"]=[[这里是古陵的正厅，厅正中端坐着一位白衣少女，厅角上摆放着一张石头做成的大床，厅中横系着一条绳子，不知道做什么用的，除此之外，别无摆设。]],["id"]=[[fb28_20]],["item1"]=[[fb28item2]],["item2"]=[[fb28item3]],["item3"]=[[fb28item4]],["left"]=[[fb28_19]],["name"]=[[正厅]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_16]]},["fb28_21"]={["dsc"]=[[这里是古陵的后厅在厅的中央，摆放着几具棺材，其中只有一具棺材的棺板没有合上，棺材中好像空空如也。正前方写着一行大字，东西两壁都挂着一幅画。]],["id"]=[[fb28_21]],["item1"]=[[fb28item112]],["item2"]=[[fb28item113]],["item3"]=[[fb28item114]],["name"]=[[后厅]],["permission"]=1,["role1"]=[[fb28r21_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb28_20]]},["fb28_22"]={["dsc"]=[[这里是寒水潭密洞的出口，一处小小的密洞，不远处有一张小小的石床和石棺，还有一道靓丽的身影。]],["id"]=[[fb28_22]],["item1"]=[[fb28item18]],["name"]=[[密室]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb28_23"]={["dsc"]=[[密室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来似乎很久以前有人在这里住过。]],["id"]=[[fb28_23]],["left"]=[[fb28_25]],["name"]=[[地下密室]],["permission"]=2,["right"]=[[fb28_26]],["stepMusic"]=[[jiaobu]],["up"]=[[fb28_24]]},["fb28_24"]={["down"]=[[fb28_23]],["dsc"]=[[密室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来似乎很久以前有人在这里住过。]],["id"]=[[fb28_24]],["name"]=[[地下密室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb28_25"]={["dsc"]=[[密室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来似乎很久以前有人在这里住过。]],["id"]=[[fb28_25]],["item1"]=[[wabaorenwu12]],["item2"]=[[wabaorenwu20]],["name"]=[[地下密室]],["permission"]=2,["right"]=[[fb28_23]],["stepMusic"]=[[jiaobu]]},["fb28_26"]={["dsc"]=[[密室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来似乎很久以前有人在这里住过。]],["id"]=[[fb28_26]],["item1"]=[[wabaorenwu19]],["left"]=[[fb28_23]],["name"]=[[地下密室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb28_27"]={["dsc"]=[[终南山上养蜂人搭建的蜂屋。饲养的都是寻常蜜蜂，正在往来采蜜。]],["id"]=[[fb28_27]],["item1"]=[[fb28item106]],["item2"]=[[fb28item109]],["item3"]=[[fb28item110]],["left"]=[[fb28_02]],["name"]=[[蜂屋]],["permission"]=2,["right"]=[[fb28_28]],["role1"]=[[fb28r27_100]],["stepMusic"]=[[jiaobu]]},["fb28_28"]={["dsc"]=[[这间屋子是养蜂人居住的场所。屋子外面晒着半干的蜂巢与一些常见的草药。]],["id"]=[[fb28_28]],["item1"]=[[fb28item107]],["left"]=[[fb28_27]],["name"]=[[木屋]],["permission"]=2,["role1"]=[[fb28r28_100]],["stepMusic"]=[[jiaobu]]},["fb28_29"]={["down"]=[[fb28_30]],["dsc"]=[[这里是一片草地，草很深，几乎淹没了小腿。草间散布着一些奇花，微风吹过，芬芳扑鼻。你听到时而有“嗡嗡”的声音，看见有一些个头奇大的蜜蜂在草地上飞舞盘旋。]],["id"]=[[fb28_29]],["name"]=[[草地]],["permission"]=2,["role1"]=[[fb28_06a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb28_05]]},["fb28_30"]={["dsc"]=[[狭长的暗道，没有光，黑漆漆的令人害怕。]],["id"]=[[fb28_30]],["item1"]=[[fubentiaozhuan1]],["name"]=[[暗道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb28_29]]}}0000000